1	import Link from "next/link";
2	import {
3	  ShieldCheck,
4	  ArrowRight,
5	  Wallet,
6	  Clock,
7	  CalendarClock,
8	  Star,
9	  Activity,
10	  CircleCheck,
11	  CircleAlert,
12	  Ban,
13	} from "lucide-react";
14	import { Card } from "@/components/ui/Card";
15	import { Button } from "@/components/ui/Button";
16	import { StatCard } from "@/components/ui/StatCard";
17	import { StatusBadge, type StatusTone } from "@/components/ui/StatusBadge";
18	import { DashboardHeader } from "@/components/dashboard/DashboardHeader";
19	import { AvailabilityToggle } from "@/components/provider/AvailabilityToggle";
20	import { IncomingRequests } from "@/components/provider/IncomingRequests";
21	import { SessionsTable } from "@/components/provider/SessionsTable";
22	import { PayoutsTable } from "@/components/provider/PayoutsTable";
