36	
37	export const metadata = {
38	  title: `${t("provider.dashboardTitle")} · ${t("app.name")}`,
39	};
40	
41	const STATUS: Record<
42	  ProviderStatus,
43	  { titleKey: MessageKey; bodyKey: MessageKey; tone: StatusTone }
44	> = {
45	  pending: {
46	    titleKey: "provider.statusPendingTitle",
47	    bodyKey: "provider.statusPendingBody",
48	    tone: "warning",
49	  },
50	  approved: {
51	    titleKey: "provider.statusApprovedTitle",
52	    bodyKey: "provider.statusApprovedBody",
53	    tone: "success",
54	  },
55	  rejected: {
56	    titleKey: "provider.statusRejectedTitle",
57	    bodyKey: "provider.statusRejectedBody",
58	    tone: "alert",
59	  },
60	  suspended: {
61	    titleKey: "provider.statusSuspendedTitle",
62	    bodyKey: "provider.statusSuspendedBody",
63	    tone: "alert",
64	  },
65	};
66	
67	export default async function ProviderDashboardPage() {
68	  const profile = await requireRole("provider");
69	  const provider = await getOwnProvider();
70	
71	  const onboardingComplete =
72	    !!provider &&
73	    provider.bio.trim().length > 0 &&
74	    provider.topics.length > 0 &&
75	    provider.price_block_30_cents > 0;
76	
77	  const [bookings, payouts, sessions, reviews] = provider
78	    ? await Promise.all([
79	        listProviderBookings(provider.id),
80	        listProviderPayouts(provider.id),
81	        listProviderCompletedSessions(provider.id),
82	        listProviderReviews(provider.id),
83	      ])
84	    : [[], [], [], []];
85	
86	  const earnings = summarizeEarnings({
87	    sessions,
88	    tips: reviews.filter((r) => r.tip_cents > 0),
89	    payouts,
90	    nowMs: nowEpochMs(),
91	  });
92	
93	  const upcoming = bookings.filter(
94	    (b) => b.status === "confirmed" || b.status === "in_progress",
95	  );
96	  const nextScheduled = bookings
97	    .filter((b) => b.scheduled_at && b.status === "confirmed")
98	    .sort((a, b) => (a.scheduled_at! < b.scheduled_at! ? -1 : 1))[0];
99	
100	  const ratingBySession = new Map(
101	    reviews.filter((r) => r.session_id).map((r) => [r.session_id, r.rating]),
102	  );
103	
104	  const status = provider?.status ?? "pending";
105	  const statusCopy = STATUS[status];
106	
107	  const sessionRows = sessions.map((s) => ({
108	    id: s.id,
109	    dateLabel: shortDate(s.ended_at),
110	    endedAtMs: s.ended_at ? new Date(s.ended_at).getTime() : 0,
111	    durationLabel: durationLabel(s.elapsed_seconds),
112	    blockMinutes: s.block_minutes,
113	    overageMinutes: s.overage_minutes,
114	    earningsCents: s.provider_earnings_cents,
115	    rating: ratingBySession.get(s.id) ?? null,
116	  }));
117	
118	  const payoutRows = payouts.map((p) => ({
119	    id: p.id,
120	    periodLabel: `${shortDate(p.period_start)} – ${shortDate(p.period_end)}`,
121	    periodEndMs: new Date(p.period_end).getTime(),
122	    amountCents: p.amount_cents,
123	    status: p.status,
124	  }));
125	
126	  const healthItems: { labelKey: MessageKey; done: boolean }[] = [
127	    { labelKey: "provider.phVoiceIntro", done: !!provider?.voice_intro_path },
128	    { labelKey: "provider.phTopics", done: (provider?.topics.length ?? 0) > 0 },
129	    {
130	      labelKey: "provider.phLanguages",
131	      done: (provider?.languages.length ?? 0) > 0,
132	    },
133	    { labelKey: "provider.phPrices", done: (provider?.price_block_30_cents ?? 0) > 0 },
134	    { labelKey: "provider.phApproval", done: status === "approved" },
135	    {
136	      labelKey: "provider.phBgCheck",
137	      done: provider?.bg_check_status === "clear",
138	    },
139	  ];
140	
141	  return (
142	    <div className="flex flex-col gap-8">
143	      <DashboardHeader
144	        title={t("provider.welcomeBack", {
145	          name: provider?.display_name || profile.full_name,
146	        })}
147	        description={t("provider.dashboardSubtitle")}
148	        action={
149	          <Link href="/provider/onboarding" className="rounded-btn">
150	            <Button variant="ghost">{t("provider.editProfile")}</Button>
151	          </Link>
152	        }
153	      />
154	
155	      {!onboardingComplete ? (
156	        <Card className="flex flex-col gap-3 bg-primary-tint sm:flex-row sm:items-center sm:justify-between">
157	          <p className="text-lg font-bold text-ink">
158	            {t("provider.completeOnboarding")}
159	          </p>
160	          <Link href="/provider/onboarding" className="rounded-btn">
161	            <Button icon={ArrowRight}>{t("provider.completeOnboarding")}</Button>
162	          </Link>
163	        </Card>
164	      ) : null}
165	
166	      {/* Availability + status */}
167	      <Card as="section" className="flex flex-col gap-4">
168	        <div className="flex flex-wrap items-center justify-between gap-3">
169	          <h2 className="text-h3">{t("provider.availabilityHeading")}</h2>
170	          <StatusBadge tone={statusCopy.tone} icon={ShieldCheck}>
171	            {t(statusCopy.titleKey)}
172	          </StatusBadge>
173	        </div>
174	        <AvailabilityToggle
175	          initial={provider?.is_available_now ?? false}
176	          disabled={status !== "approved"}
177	        />
178	        <p className="text-base text-ink-soft">
179	          {nextScheduled
180	            ? `${t("provider.nextScheduled")}: ${shortDate(nextScheduled.scheduled_at)} · ${t("provider.minutesShort", { minutes: nextScheduled.block_minutes })}`
181	            : t("provider.nextScheduledNone")}
182	        </p>
183	      </Card>
184	
185	      {/* At a glance */}
186	      <section className="flex flex-col gap-4">
187	        <h2 className="text-h2">{t("provider.glanceHeading")}</h2>
188	        <div className="grid grid-cols-4 gap-4 max-lg:grid-cols-2 max-sm:grid-cols-1">
189	          <StatCard
190	            label={t("provider.earningsHeading")}
191	            value={formatCents(earnings.thisWeekCents)}
192	            icon={Wallet}
193	          />
194	          <StatCard
195	            label={t("provider.statPending")}
196	            value={formatCents(earnings.pendingCents)}
197	            icon={Clock}
198	          />
199	          <StatCard
200	            label={t("provider.statNextPayout")}
201	            value={
202	              earnings.nextPayoutAt
203	                ? shortDate(earnings.nextPayoutAt)
204	                : t("provider.noNextPayout")
205	            }
206	            icon={CalendarClock}
207	          />
208	          <StatCard
209	            label={t("provider.statAvgRating")}
210	            value={
211	              provider && provider.rating_count > 0
212	                ? formatRating(provider.rating_avg)
213	                : t("provider.noRatingShort")
214	            }
215	            hint={
216	              provider && provider.rating_count > 0
217	                ? `${provider.rating_count} reviews`
218	                : undefined
219	            }
220	            icon={Star}
221	          />
222	          <StatCard
223	            label={t("provider.statSessionsWeek")}
224	            value={earnings.sessionsThisWeek}
225	            icon={Activity}
226	          />
227	        </div>
228	      </section>
229	
230	      {/* Incoming & upcoming */}
231	      <section className="flex flex-col gap-4">
232	        <h2 className="text-h2">{t("provider.incomingHeading")}</h2>
233	        <IncomingRequests
234	          items={upcoming.map((b) => ({
235	            id: b.id,
236	            blockMinutes: b.block_minutes,
237	            status: b.status as "confirmed" | "in_progress",
238	          }))}
239	        />
240	      </section>
241	
242	      {/* Recent sessions */}
243	      <section className="flex flex-col gap-4">
244	        <h2 className="text-h2">{t("provider.recentSessionsHeading")}</h2>
245	        <SessionsTable rows={sessionRows} />
246	      </section>
247	
248	      {/* Earnings & payouts */}
249	      <section className="flex flex-col gap-4">
250	        <h2 className="text-h2">{t("provider.earningsHeading")}</h2>
251	        <div className="grid grid-cols-3 gap-4 max-sm:grid-cols-1">
252	          <StatCard
253	            label={t("provider.earningsBalanceLabel")}
254	            value={formatCents(earnings.pendingCents)}
255	          />
256	          <StatCard
257	            label={t("provider.earningsMonthLabel")}
258	            value={formatCents(earnings.thisMonthCents)}
259	          />
260	          <StatCard
261	            label={t("provider.earningsLifetimeLabel")}
262	            value={formatCents(earnings.lifetimeCents)}
263	          />
264	        </div>
265	        <h3 className="text-h3">{t("provider.payoutHistoryHeading")}</h3>
266	        <PayoutsTable rows={payoutRows} />
267	      </section>
268	
269	      {/* Feedback */}
270	      <section className="flex flex-col gap-4">
271	        <h2 className="text-h2">{t("provider.feedbackHeading")}</h2>
272	        {reviews.length === 0 ? (
273	          <Card>
274	            <p className="text-base text-ink-soft">{t("provider.feedbackNone")}</p>
275	          </Card>
276	        ) : (
277	          <ul className="flex flex-col gap-3">
278	            {reviews.slice(0, 5).map((r) => (
279	              <Card as="li" key={r.id} className="flex flex-col gap-1.5">
280	                <div className="flex items-center justify-between gap-3">
281	                  <span className="text-base font-bold text-ink">
282	                    {"★".repeat(r.rating)}
283	                    <span className="sr-only"> {r.rating} of 5</span>
284	                  </span>
285	                  {r.tip_cents > 0 ? (
286	                    <StatusBadge tone="info" icon={Wallet}>
287	                      {t("provider.tipLabel", { amount: formatCents(r.tip_cents) })}
288	                    </StatusBadge>
289	                  ) : null}
290	                </div>
291	                {r.comment ? (
292	                  <p className="text-base text-ink">{r.comment}</p>
293	                ) : null}
294	              </Card>
295	            ))}
296	          </ul>
297	        )}
298	      </section>
299	
300	      {/* Profile health */}
301	      <section className="flex flex-col gap-4">
302	        <div className="flex flex-wrap items-center justify-between gap-3">
303	          <h2 className="text-h2">{t("provider.profileHealthHeading")}</h2>
304	          <Link href="/provider/onboarding" className="rounded-btn">
305	            <Button variant="ghost">{t("provider.editProfile")}</Button>
306	          </Link>
307	        </div>
308	        <ul className="grid grid-cols-2 gap-3 max-sm:grid-cols-1">
309	          {healthItems.map((item) => (
310	            <Card
311	              as="li"
312	              key={item.labelKey}
313	              className="flex items-center justify-between gap-3"
314	            >
315	              <span className="text-base font-bold text-ink">
316	                {t(item.labelKey)}
317	              </span>
318	              {item.done ? (
319	                <StatusBadge tone="success" icon={CircleCheck}>
320	                  {t("provider.phDone")}
321	                </StatusBadge>
322	              ) : status === "rejected" || status === "suspended" ? (
323	                <StatusBadge tone="alert" icon={Ban}>
324	                  {t("provider.phMissing")}
325	                </StatusBadge>
326	              ) : (
327	                <StatusBadge tone="warning" icon={CircleAlert}>
328	                  {t("provider.phMissing")}
329	                </StatusBadge>
330	              )}
331	            </Card>
332	          ))}
333	        </ul>
334	      </section>
335	    </div>
336	  );
337	}
