1	"use client";
2	
3	import * as React from "react";
4	import { useTransition } from "react";
5	import Link from "next/link";
6	import { Phone, X, Clock } from "lucide-react";
7	import { Card } from "@/components/ui/Card";
8	import { Button } from "@/components/ui/Button";
9	import { StatusBadge } from "@/components/ui/StatusBadge";
10	import { declineBooking } from "@/app/(provider)/provider/actions";
11	import { t } from "@/lib/i18n";
12	import { useToast } from "@/components/ui/Toast";
13	
14	export interface IncomingItem {
15	  id: string;
16	  blockMinutes: number;
17	  status: "confirmed" | "in_progress";
18	}
19	
20	export function IncomingRequests({ items }: { items: IncomingItem[] }) {
21	  const [pending, startTransition] = useTransition();
22	  const { announce } = useToast();
23	
24	  function decline(id: string) {
25	    startTransition(async () => {
26	      await declineBooking(id);
27	      announce(t("provider.decline"));
28	    });
29	  }
30	
31	  if (items.length === 0) {
32	    return (
33	      <Card>
34	        <p className="text-base text-ink-soft">{t("provider.incomingNone")}</p>
35	      </Card>
36	    );
37	  }
38	
39	  return (
40	    <ul className="flex flex-col gap-3">
41	      {items.map((item) => (
42	        <Card
43	          as="li"
44	          key={item.id}
45	          className="flex flex-wrap items-center justify-between gap-3"
46	        >
47	          <div className="flex items-center gap-3">
48	            <StatusBadge
49	              tone={item.status === "in_progress" ? "info" : "success"}
50	              icon={item.status === "in_progress" ? Clock : Phone}
51	            >
52	              {t("provider.guest")}
53	            </StatusBadge>
54	            <span className="text-base font-bold text-ink">
55	              {t("provider.minutesShort", { minutes: item.blockMinutes })}
56	            </span>
57	          </div>
58	          <div className="flex items-center gap-2">
59	            <Link href={`/provider/session/${item.id}`} className="rounded-btn">
60	              <Button icon={Phone}>{t("provider.accept")}</Button>
61	            </Link>
62	            <Button
63	              variant="ghost"
64	              icon={X}
65	              onClick={() => decline(item.id)}
66	              disabled={pending}
67	            >
68	              {t("provider.decline")}
69	            </Button>
70	          </div>
71	        </Card>
72	      ))}
73	    </ul>
74	  );
75	}
