11	  message: string;
12	  tone: ToastTone;
13	}
14	
15	interface ToastApi {
16	  /** Show a dismissible visual toast (also announced to screen readers). */
17	  toast: (message: string, tone?: ToastTone) => void;
18	  /** Announce a state change to screen readers only (no visual chrome). */
19	  announce: (message: string, assertive?: boolean) => void;
20	}
21	
22	const ToastContext = React.createContext<ToastApi | null>(null);
23	
24	const TONE: Record<ToastTone, { icon: typeof Info; className: string }> = {
25	  success: { icon: CircleCheck, className: "border-success text-success" },
26	  alert: { icon: CircleAlert, className: "border-alert text-alert" },
27	  info: { icon: Info, className: "border-primary text-primary" },
28	};
